import{_ as i,c as a,o as s,ag as r}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"Dépannage","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/troubleshooting.md","filePath":"fr/guide/troubleshooting.md","lastUpdated":1794112334000}'),n={name:"fr/guide/troubleshooting.md"};function o(t,e,l,p,d,u){return s(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="depannage" tabindex="-1">Dépannage <a class="header-anchor" href="#depannage" aria-label="Permalink to &quot;Dépannage&quot;">​</a></h1><h2 id="problemes-courants" tabindex="-1">Problèmes courants <a class="header-anchor" href="#problemes-courants" aria-label="Permalink to &quot;Problèmes courants&quot;">​</a></h2><h3 id="l-application-ne-demarre-pas" tabindex="-1">L&#39;application ne démarre pas <a class="header-anchor" href="#l-application-ne-demarre-pas" aria-label="Permalink to &quot;L&#39;application ne démarre pas&quot;">​</a></h3><p><strong>Symptômes</strong> : Nicasa ne se lance pas ou plante immédiatement</p><p><strong>Solutions</strong> :</p><ol><li>Vérifiez que vous utilisez macOS 10.13 ou version ultérieure</li><li>Vérifiez que vous disposez d&#39;au moins 4 Go de RAM</li><li>Redémarrez votre Mac</li><li>Réinstallez Nicasa depuis le Mac App Store</li><li>Vérifiez la présence d&#39;applications en conflit</li></ol><h3 id="les-captures-d-ecran-ne-fonctionnent-pas" tabindex="-1">Les captures d&#39;écran ne fonctionnent pas <a class="header-anchor" href="#les-captures-d-ecran-ne-fonctionnent-pas" aria-label="Permalink to &quot;Les captures d&#39;écran ne fonctionnent pas&quot;">​</a></h3><p><strong>Symptômes</strong> : la fonction de capture d&#39;écran ne fonctionne pas</p><p><strong>Solutions</strong> :</p><ol><li><strong>Accordez l&#39;autorisation d&#39;enregistrement de l&#39;écran</strong> : <ul><li>Allez dans Réglages Système &gt; Confidentialité et sécurité &gt; Enregistrement de l&#39;écran</li><li>Cochez la case en face de Nicasa</li><li>Redémarrez Nicasa</li></ul></li><li>Vérifiez qu&#39;aucun autre outil de capture n&#39;est en cours d&#39;exécution</li><li>Essayez de redémarrer votre Mac</li></ol><h3 id="l-extension-chrome-ne-fonctionne-pas" tabindex="-1">L&#39;extension Chrome ne fonctionne pas <a class="header-anchor" href="#l-extension-chrome-ne-fonctionne-pas" aria-label="Permalink to &quot;L&#39;extension Chrome ne fonctionne pas&quot;">​</a></h3><p><strong>Symptômes</strong> : l&#39;extension n&#39;apparaît pas ou n&#39;extrait pas d&#39;images</p><p><strong>Solutions</strong> :</p><ol><li>Vérifiez que l&#39;extension est activée dans Chrome</li><li>Vérifiez que vous utilisez une version compatible de Chrome</li><li>Essayez d&#39;actualiser la page web</li><li>Réinstallez l&#39;extension</li><li>Videz le cache et les cookies du navigateur</li></ol><h3 id="les-images-ne-se-chargent-pas" tabindex="-1">Les images ne se chargent pas <a class="header-anchor" href="#les-images-ne-se-chargent-pas" aria-label="Permalink to &quot;Les images ne se chargent pas&quot;">​</a></h3><p><strong>Symptômes</strong> : les miniatures n&#39;apparaissent pas ou les images ne s&#39;ouvrent pas</p><p><strong>Solutions</strong> :</p><ol><li>Vérifiez les autorisations des fichiers image</li><li>Assurez-vous que les images ne sont pas corrompues</li><li>Vérifiez que le format est pris en charge (JPEG, PNG, GIF, BMP, TIFF, WebP)</li><li>Essayez de rouvrir le dossier</li><li>Redémarrez Nicasa</li></ol><h3 id="performances-lentes" tabindex="-1">Performances lentes <a class="header-anchor" href="#performances-lentes" aria-label="Permalink to &quot;Performances lentes&quot;">​</a></h3><p><strong>Symptômes</strong> : l&#39;application est lente ou les miniatures se chargent lentement</p><p><strong>Solutions</strong> :</p><ol><li>Fermez les autres applications gourmandes en mémoire</li><li>Vérifiez que vous disposez de suffisamment de RAM libre (8 Go recommandés)</li><li>Réduisez la taille de la grille de miniatures dans les préférences</li><li>Videz le cache de l&#39;application</li><li>Redémarrez votre Mac</li></ol><h3 id="l-editeur-ia-ne-fonctionne-pas" tabindex="-1">L&#39;éditeur IA ne fonctionne pas <a class="header-anchor" href="#l-editeur-ia-ne-fonctionne-pas" aria-label="Permalink to &quot;L&#39;éditeur IA ne fonctionne pas&quot;">​</a></h3><p><strong>Symptômes</strong> : les outils d&#39;édition par IA sont indisponibles ou ne fonctionnent pas</p><p><strong>Solutions</strong> :</p><ol><li>Vérifiez que votre connexion internet est stable (pour certaines fonctions)</li><li>Vérifiez que votre Mac répond à la configuration minimale</li><li>Redémarrez Nicasa</li><li>Mettez à jour vers la dernière version</li><li>Contactez l&#39;assistance si le problème persiste</li></ol><h3 id="problemes-d-autorisations" tabindex="-1">Problèmes d&#39;autorisations <a class="header-anchor" href="#problemes-d-autorisations" aria-label="Permalink to &quot;Problèmes d&#39;autorisations&quot;">​</a></h3><p><strong>Symptômes</strong> : l&#39;application demande des autorisations ou certaines fonctions ne marchent pas</p><p><strong>Solutions</strong> :</p><ol><li><strong>Enregistrement de l&#39;écran</strong> : Réglages Système &gt; Confidentialité et sécurité &gt; Enregistrement de l&#39;écran</li><li><strong>Accessibilité</strong> : Réglages Système &gt; Confidentialité et sécurité &gt; Accessibilité (pour le mode superposition)</li><li><strong>Fichiers et dossiers</strong> : Réglages Système &gt; Confidentialité et sécurité &gt; Fichiers et dossiers</li><li>Redémarrez Nicasa après avoir accordé les autorisations</li></ol><h3 id="problemes-avec-le-mode-superposition" tabindex="-1">Problèmes avec le mode superposition <a class="header-anchor" href="#problemes-avec-le-mode-superposition" aria-label="Permalink to &quot;Problèmes avec le mode superposition&quot;">​</a></h3><p><strong>Symptômes</strong> : le mode superposition transparente ne fonctionne pas correctement</p><p><strong>Solutions</strong> :</p><ol><li>Accordez l&#39;autorisation d&#39;accessibilité dans Réglages Système</li><li>Vérifiez qu&#39;aucun autre outil de superposition n&#39;est en cours d&#39;exécution</li><li>Essayez de désactiver puis réactiver le mode superposition</li><li>Redémarrez Nicasa</li></ol><h2 id="messages-d-erreur" tabindex="-1">Messages d&#39;erreur <a class="header-anchor" href="#messages-d-erreur" aria-label="Permalink to &quot;Messages d&#39;erreur&quot;">​</a></h2><h3 id="«-autorisation-d-enregistrement-de-l-ecran-requise-»" tabindex="-1">« Autorisation d&#39;enregistrement de l&#39;écran requise » <a class="header-anchor" href="#«-autorisation-d-enregistrement-de-l-ecran-requise-»" aria-label="Permalink to &quot;« Autorisation d&#39;enregistrement de l&#39;écran requise »&quot;">​</a></h3><p><strong>Solution</strong> : accordez l&#39;autorisation d&#39;enregistrement de l&#39;écran comme décrit ci-dessus dans la section « Les captures d&#39;écran ne fonctionnent pas ».</p><h3 id="«-impossible-de-charger-l-image-»" tabindex="-1">« Impossible de charger l&#39;image » <a class="header-anchor" href="#«-impossible-de-charger-l-image-»" aria-label="Permalink to &quot;« Impossible de charger l&#39;image »&quot;">​</a></h3><p><strong>Causes possibles</strong> :</p><ul><li>Le fichier est corrompu</li><li>Format non pris en charge</li><li>Problème d&#39;autorisations du fichier</li><li>Le fichier est trop volumineux</li></ul><p><strong>Solutions</strong> :</p><ol><li>Essayez d&#39;ouvrir le fichier avec Aperçu pour vérifier qu&#39;il est valide</li><li>Convertissez-le dans un format pris en charge</li><li>Vérifiez les autorisations du fichier</li><li>Vérifiez que la taille du fichier est raisonnable</li></ol><h3 id="«-l-extension-ne-repond-pas-»" tabindex="-1">« L&#39;extension ne répond pas » <a class="header-anchor" href="#«-l-extension-ne-repond-pas-»" aria-label="Permalink to &quot;« L&#39;extension ne répond pas »&quot;">​</a></h3><p><strong>Solution</strong> : actualisez la page web et réessayez. Si le problème persiste, réinstallez l&#39;extension.</p><h2 id="obtenir-de-l-aide" tabindex="-1">Obtenir de l&#39;aide <a class="header-anchor" href="#obtenir-de-l-aide" aria-label="Permalink to &quot;Obtenir de l&#39;aide&quot;">​</a></h2><p>Si les problèmes persistent :</p><ol><li>Consultez ce guide de dépannage</li><li>Rendez-vous sur notre <a href="/fr/guide/faq.html">FAQ</a></li><li>Ouvrez un ticket sur <a href="https://github.com/nicasa-app/nicasa-support/issues" target="_blank" rel="noreferrer">GitHub</a></li><li>Indiquez votre version de macOS, la version de Nicasa et les étapes détaillées pour reproduire le problème</li></ol><h2 id="informations-systeme" tabindex="-1">Informations système <a class="header-anchor" href="#informations-systeme" aria-label="Permalink to &quot;Informations système&quot;">​</a></h2><p>Lors d&#39;un signalement, veuillez inclure :</p><ul><li>Version de macOS (menu Apple &gt; À propos de ce Mac)</li><li>Version de Nicasa (Nicasa &gt; À propos de Nicasa)</li><li>Modèle et puce du Mac (Apple Silicon ou Intel)</li><li>Étapes pour reproduire le problème</li><li>Tous les messages d&#39;erreur</li></ul><p>Cela signifie généralement que le fichier image a été déplacé ou supprimé. Essayez de rouvrir le dossier ou de sélectionner un autre répertoire.</p><h3 id="«-format-non-pris-en-charge-»" tabindex="-1">« Format non pris en charge » <a class="header-anchor" href="#«-format-non-pris-en-charge-»" aria-label="Permalink to &quot;« Format non pris en charge »&quot;">​</a></h3><p>Le format de l&#39;image n&#39;est pas reconnu. Consultez notre liste des <a href="/fr/guide/usage.html">formats pris en charge</a> ou convertissez l&#39;image dans un format compatible.</p><h3 id="«-memoire-insuffisante-»" tabindex="-1">« Mémoire insuffisante » <a class="header-anchor" href="#«-memoire-insuffisante-»" aria-label="Permalink to &quot;« Mémoire insuffisante »&quot;">​</a></h3><p>Votre système manque de RAM. Fermez d&#39;autres applications ou augmentez votre mémoire.</p><h2 id="depannage-avance" tabindex="-1">Dépannage avancé <a class="header-anchor" href="#depannage-avance" aria-label="Permalink to &quot;Dépannage avancé&quot;">​</a></h2><h3 id="consulter-les-journaux" tabindex="-1">Consulter les journaux <a class="header-anchor" href="#consulter-les-journaux" aria-label="Permalink to &quot;Consulter les journaux&quot;">​</a></h3><p>Pour accéder aux journaux de l&#39;application :</p><ol><li>Allez dans Aide &gt; Afficher les journaux</li><li>Ou trouvez les journaux dans : <ul><li>Windows : <code>%APPDATA%\\Nicasa\\logs</code></li><li>macOS : <code>~/Library/Application Support/Nicasa/logs</code></li><li>Linux : <code>~/.config/Nicasa/logs</code></li></ul></li></ol><h3 id="reinitialiser-l-application" tabindex="-1">Réinitialiser l&#39;application <a class="header-anchor" href="#reinitialiser-l-application" aria-label="Permalink to &quot;Réinitialiser l&#39;application&quot;">​</a></h3><p>Pour rétablir tous les réglages par défaut :</p><ol><li>Fermez Nicasa</li><li>Supprimez le dossier de données de l&#39;application</li><li>Redémarrez Nicasa</li></ol><h3 id="options-de-ligne-de-commande" tabindex="-1">Options de ligne de commande <a class="header-anchor" href="#options-de-ligne-de-commande" aria-label="Permalink to &quot;Options de ligne de commande&quot;">​</a></h3><p>Pour les utilisateurs avancés, Nicasa prend en charge les arguments de ligne de commande :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Activer la journalisation détaillée</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --reset-settings</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Réinitialiser tous les réglages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nicasa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/folder</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Ouvrir un dossier précis</span></span></code></pre></div><h2 id="obtenir-plus-d-aide" tabindex="-1">Obtenir plus d&#39;aide <a class="header-anchor" href="#obtenir-plus-d-aide" aria-label="Permalink to &quot;Obtenir plus d&#39;aide&quot;">​</a></h2><p>Si ces solutions ne résolvent pas votre problème :</p><ol><li>Consultez notre <a href="/fr/guide/faq.html">FAQ</a></li><li>Recherchez dans les <a href="https://github.com/nicasa-project/nicasa-support/issues" target="_blank" rel="noreferrer">tickets</a> existants</li><li>Créez un nouveau ticket avec : <ul><li>Votre système d&#39;exploitation et sa version</li><li>La version de Nicasa</li><li>Les étapes pour reproduire le problème</li><li>Tous les messages d&#39;erreur ou captures d&#39;écran</li></ul></li></ol>`,68)])])}const h=i(n,[["render",o]]);export{m as __pageData,h as default};
